                    "content": "#include \"bst.h\"\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic Node *new_node(int key, Node *parent) {\n    Node *node = malloc(sizeof(*node));\n    if (node == NULL) return NULL;\n    node->key = key;\n    node->left = NULL;\n    node->right = NULL;\n    node->parent = parent;\n    return node;\n}\n\nNode *bst_insert(Node *root, int key) {\n    if (root == NULL) return new_node(key, NULL);\n    Node *current = root;\n    for (;;) {\n        if (key < current->key) {\n            if (current->left == NULL) { current->left = new_node(key, current); break; }\n            current = current->left;\n        } else {\n            if (current->right == NULL) { current->right = new_node(key, current); break; }\n            current = current->right;\n        }\n    }\n    return root;\n}\n\nstatic Node *build_range(const int *sorted, size_t begin, size_t end, Node *parent) {\n    if (begin >= end) return NULL;\n    const size_t middle = begin + (end - begin) / 2;\n    Node *root = new_node(sorted[middle], parent);\n    if (root == NULL) return NULL;\n    root->left = build_range(sorted, begin, middle, root);\n    root->right = build_range(sorted, middle + 1, end, root);\n    return root;\n}\n\nNode *bst_build_balanced(const int *sorted, size_t n) {\n    return build_range(sorted, 0, n, NULL);\n}\n\nstatic size_t bst_count(const Node *root) {\n    return root == NULL ? 0 : 1 + bst_count(root->left) + bst_count(root->right);\n}\n\nstatic void inorder_fill(const Node *root, int *values, size_t *next) {\n    if (root == NULL) return;\n    inorder_fill(root->left, values, next);\n    values[(*next)++] = root->key;\n    inorder_fill(root->right, values, next);\n}\n\nNode *bst_rebalance(Node *root) {\n    const size_t n = bst_count(root);\n    if (n < 2) return root;\n\n    int *values = malloc(n * sizeof(*values));\n    if (values == NULL) return root;\n\n    size_t next = 0;\n    inorder_fill(root, values, &next);\n    bst_free(root);\n    Node *balanced = bst_build_balanced(values, n);\n    free(values);\n    return balanced;\n}\n\nstatic size_t check_balance(const Node *root, bool *ok) {\n    if (root == NULL) return 0;\n    size_t left = check_balance(root->left, ok);\n    size_t right = check_balance(root->right, ok);\n    if (left > right + 1 || right > left + 1) *ok = false;\n    return left + right + 1;\n}\n\nbool bst_is_almost_balanced(const Node *root) { bool ok = true; check_balance(root, &ok); return ok; }\nint bst_height(const Node *root) { if (root == NULL) return 0; int l=bst_height(root->left), r=bst_height(root->right); return 1 + (l > r ? l : r); }\nvoid bst_print_inorder(const Node *root) { if (root == NULL) return; bst_print_inorder(root->left); printf(\"%d \", root->key); bst_print_inorder(root->right); }\nvoid bst_free(Node *root) { if (root == NULL) return; bst_free(root->left); bst_free(root->right); free(root); }\n"
