                "starterCode": "#include <stdio.h>\n#include \"ratios.h\"\nint main(void) {\n    printf(\"poly_ratio_n1000=%.6f\\n\", polynomial_ratio(1000.0));\n    printf(\"degree_ratio_n1000=%.6f\\n\", lower_degree_ratio(1000.0));\n    printf(\"exp_ratio_n20=%.6f\\n\", exponential_ratio(20));\n    return 0;\n}\n",
                "solutionCode": "#include <stdio.h>\n#include \"ratios.h\"\nint main(void) {\n    printf(\"poly_ratio_n1000=%.6f\\n\", polynomial_ratio(1000.0));\n    printf(\"degree_ratio_n1000=%.6f\\n\", lower_degree_ratio(1000.0));\n    printf(\"exp_ratio_n20=%.6f\\n\", exponential_ratio(20));\n    return 0;\n}\n",
                "starterFiles": {
                  "main_c": {
                    "content": "#include <stdio.h>\n#include \"ratios.h\"\nint main(void) {\n    printf(\"poly_ratio_n1000=%.6f\\n\", polynomial_ratio(1000.0));\n    printf(\"degree_ratio_n1000=%.6f\\n\", lower_degree_ratio(1000.0));\n    printf(\"exp_ratio_n20=%.6f\\n\", exponential_ratio(20));\n    return 0;\n}\n"
                  },
                  "ratios_h": {
                    "content": "#ifndef RATIOS_H\n#define RATIOS_H\ndouble polynomial_ratio(double n);\ndouble lower_degree_ratio(double n);\ndouble exponential_ratio(int n);\n#endif\n"
                  },
                  "ratios_c": {
                    "content": "#include \"ratios.h\"\ndouble polynomial_ratio(double n) { (void)n; return 0.0; }\ndouble lower_degree_ratio(double n) { (void)n; return 0.0; }\ndouble exponential_ratio(int n) { (void)n; return 0.0; }\n"
                  }
                },
                "solutionFiles": {
                  "main_c": {
                    "content": "#include <stdio.h>\n#include \"ratios.h\"\nint main(void) {\n    printf(\"poly_ratio_n1000=%.6f\\n\", polynomial_ratio(1000.0));\n    printf(\"degree_ratio_n1000=%.6f\\n\", lower_degree_ratio(1000.0));\n    printf(\"exp_ratio_n20=%.6f\\n\", exponential_ratio(20));\n    return 0;\n}\n"
                  },
                  "ratios_h": {
                    "content": "#ifndef RATIOS_H\n#define RATIOS_H\ndouble polynomial_ratio(double n);\ndouble lower_degree_ratio(double n);\ndouble exponential_ratio(int n);\n#endif\n"
                  },
                  "ratios_c": {
                    "content": "#include \"ratios.h\"\ndouble polynomial_ratio(double n) { return (3.0 * n * n + 7.0 * n) / (2.0 * n * n); }\ndouble lower_degree_ratio(double n) { return (2.0 * n * n * n * n - 3.0 * n * n + 7.0) / (n * n * n * n * n); }\ndouble exponential_ratio(int n) {\n    double ratio = 1.0;\n    for (int i = 0; i < n; i++) ratio *= 2.0 / 3.0;\n    return ratio;\n}\n"
                  }
                },
