          "practice": {
            "ignore-generated-files-single-choice-0": {
              "title": "Purpose of .gitignore",
              "prompt": "What is the primary purpose of a `.gitignore` file in a Git repository?",
              "hint": "A `.gitignore` rule prevents matching untracked paths from entering ordinary staging and status workflows.",
              "help": {
                "concept": "Write narrow ignore rules, prove which rule matches, and separate “ignored” from “already tracked.”",
                "hint_1": "Remove options that act on a different repository layer than the one named in the question.",
                "hint_2": "Choose the answer that remains accurate even when other unrelated files exist."
              },
              "options": {
                "a": "To track changes in all files",
                "b": "To ignore specific files and directories",
                "c": "To delete files from the repository",
                "d": "To rename files in the repository"
              }
            },
            "ignore-generated-files-single-choice-1": {
              "title": "Effect of Adding to .gitignore",
              "prompt": "What happens when you add a file to `.gitignore` that has already been committed?",
              "hint": "Ignore rules do not retroactively untrack a file that is already part of repository history.",
              "help": {
                "concept": "Write narrow ignore rules, prove which rule matches, and separate “ignored” from “already tracked.”",
                "hint_1": "Remove options that act on a different repository layer than the one named in the question.",
                "hint_2": "Choose the answer that remains accurate even when other unrelated files exist."
              },
              "options": {
                "a": "The file is automatically deleted from the repository",
                "b": "The file is untracked and removed from history",
                "c": "The file remains tracked and in history",
                "d": "The file is renamed in the repository"
              }
            },
            "ignore-generated-files-multi-choice-0": {
              "title": "Verify the Ignore Policy",
              "prompt": "Which statements describe the generated-file policy in this lesson? Select all that apply.",
              "hint": "Separate the local file from Git tracking: the summary stays on disk while the ignore rule keeps it out of future snapshots.",
              "help": {
                "concept": "Write narrow ignore rules, prove which rule matches, and separate “ignored” from “already tracked.”",
                "hint_1": "A partly true option is still wrong if it adds an effect Git does not guarantee.",
                "hint_2": "Use the layer named in the prompt—working tree, staging area, or history—to test each choice."
              },
              "options": {
                "a": "`.gitignore` contains the rule `generated/`.",
                "b": "`generated/summary.txt` remains available locally.",
                "c": "`git rm --cached` deletes the local summary from disk.",
                "d": "Ignored files still appear in ordinary `git status --short` output."
              }
            },
            "ignore-generated-files-drag-reorder-0": {
              "title": "Stop Tracking a Local-Only File",
              "prompt": "Arrange the safe steps for a file that is already tracked but should remain only on each developer’s machine.",
              "hint": "Start with the state that must exist before the next action can make sense.",
              "help": {
                "concept": "Write narrow ignore rules, prove which rule matches, and separate “ignored” from “already tracked.”",
                "hint_1": "Track how the project moves from working files to a proposed snapshot and then to history.",
                "hint_2": "Read the ordered steps as one continuous repository story."
              },
              "tokens": {
                "t1": "Add a narrow ignore rule",
                "t2": "Remove the path from Git’s index while keeping the working copy",
                "t3": "Commit the policy change"
              }
            }
          }
