        "percentage-and-discount-calculations": {
          "label": "Percentage and Discount Calculations",
          "summary": "Translate a percentage stored in the table into gross, discount, and net monetary values.",
          "cards": {
            "sketch0": {
              "title": "Calculate a Percentage of Gross Sales"
            },
            "sketch1": {
              "title": "Subtract the Discount to Find Net Sales"
            },
            "quiz": {
              "title": "Check Your Understanding"
            }
          },
          "practice": {
            "single-choice-1": {
              "title": "Convert Percent to Rate",
              "prompt": "How is a stored discount value of 15 converted to a decimal rate?",
              "hint": "A percentage must be divided by one hundred.",
              "help": {
                "concept": "15 percent equals 0.15 as a rate.",
                "hint_1": "The conversion should make the number smaller than one.",
                "hint_2": "Choose the division expression."
              },
              "options": {
                "a": "15 * 100",
                "b": "15 / 100",
                "c": "15 + 100",
                "d": "100 / 15"
              }
            },
            "single-choice-2": {
              "title": "Net Sales Definition",
              "prompt": "Which formula calculates net sales?",
              "hint": "The discount reduces the gross amount.",
              "help": {
                "concept": "Net sales is the amount remaining after the discount.",
                "hint_1": "Start with gross value and subtract the reduction.",
                "hint_2": "Choose the formula that lowers gross sales."
              },
              "options": {
                "a": "gross_sales + discount_amount",
                "b": "gross_sales - discount_amount",
                "c": "discount_amount - gross_sales",
                "d": "gross_sales * 100"
              }
            },
            "multi-choice-1": {
              "title": "Parts of a Discount Calculation",
              "prompt": "Which inputs are needed to calculate discount dollars for an order? Select all that apply.",
              "hint": "Discount dollars depend on gross value and the discount rate.",
              "help": {
                "concept": "Gross sales uses quantity and unit price.",
                "hint_1": "The percentage determines the reduction.",
                "hint_2": "The representative name is descriptive, not numeric input."
              },
              "options": {
                "a": "quantity",
                "b": "unit_price",
                "c": "discount_pct",
                "d": "sales_rep"
              }
            },
            "multi-choice-2": {
              "title": "Correct Percentage Expressions",
              "prompt": "Which expressions correctly calculate discount amount? Select all that apply.",
              "hint": "The percentage must be converted to a rate and applied to gross sales.",
              "help": {
                "concept": "Equivalent parentheses can make the two parts clearer.",
                "hint_1": "Multiplying by 10 instead of 0.10 would greatly overstate the discount.",
                "hint_2": "Look for both gross value and division by 100."
              },
              "options": {
                "a": "quantity * unit_price * COALESCE(discount_pct, 0) / 100",
                "b": "(quantity * unit_price) * (COALESCE(discount_pct, 0) / 100)",
                "c": "quantity * unit_price * COALESCE(discount_pct, 0)",
                "d": "COALESCE(discount_pct, 0) / quantity"
              }
            },
            "drag-reorder-1": {
              "title": "Build Net Sales",
              "prompt": "Arrange the calculation steps.",
              "hint": "Gross and discount amount must exist before net sales can be found.",
              "help": {
                "concept": "The rate is applied to gross value before subtraction.",
                "hint_1": "Start with the order value.",
                "hint_2": "End with the amount remaining."
              },
              "tokens": {
                "t1": "Calculate quantity * unit_price",
                "t2": "Calculate the null-safe discount rate",
                "t3": "Multiply gross sales by the rate",
                "t4": "Subtract the discount amount from gross sales"
              }
            },
            "fill-blank-choice-1": {
              "title": "Complete the Percentage Conversion",
              "prompt": "Fill the divisor that converts a whole-number percentage to a rate.",
              "hint": "Percent means “per hundred.”",
              "help": {
                "concept": "The stored value 10 should become 0.10.",
                "hint_1": "Choose the divisor that moves the decimal two places left.",
                "hint_2": "This is a conversion, not a rounding rule."
              },
              "template": "COALESCE(discount_pct, 0) / [blank1]",
              "choices": [
                "100",
                "10",
                "1",
                "0"
              ]
            }
          },
          "tryIt": {
            "allowReveal": true,
            "try_percentage_and_discount_calculations_sketch0": {
              "title": "Calculate Discounted Unit Prices",
              "prompt": "For each order, return `order_id`, `product_name`, and `unit_price`. Return `order_id, product_name, unit_price, unit_price * COALESCE(discount_pct, 0) / 100 AS unit_discount, unit_price * (1 - COALESCE(discount_pct, 0) / 100) AS discounted_unit_price` from `sales_reporting` in that column order.",
              "hint": "Apply the percentage to `unit_price`, then subtract that unit discount from the original unit price.",
              "help": {
                "concept": "Read the brief as a result contract: identify the source table or join path, the result columns, the row condition or grouping rule, and any required ordering.",
                "hint_1": "Build the result one clause at a time and run it after each meaningful change.",
                "hint_2": "Return `order_id, product_name, unit_price, unit_price * COALESCE(discount_pct, 0) / 100 AS unit_discount, unit_price * (1 - COALESCE(discount_pct, 0) / 100) AS discounted_unit_price` from `sales_reporting` in that column order."
              },
              "starterCode": "-- Write the query below.",
              "solutionCode": "SELECT\n    order_id,\n    product_name,\n    unit_price,\n    unit_price * COALESCE(discount_pct, 0) / 100 AS unit_discount,\n    unit_price * (1 - COALESCE(discount_pct, 0) / 100) AS discounted_unit_price\nFROM sales_reporting;"
            },
            "try_percentage_and_discount_calculations_sketch1": {
              "title": "Calculate Net Value for Pending Orders",
              "prompt": "For pending orders, return `order_id`, `product_name`, and null-safe `net_sales` rounded to two decimals. Return `order_id, product_name, ROUND( quantity * unit_price - quantity * unit_price * COALESCE(discount_pct, 0) / 100, 2 ) AS net_sales` from `sales_reporting` in that column order. Keep only rows where `order_status = 'Pending'`.",
              "hint": "Subtract the discount expression from gross sales, then round the completed result.",
              "help": {
                "concept": "Read the brief as a result contract: identify the source table or join path, the result columns, the row condition or grouping rule, and any required ordering.",
                "hint_1": "Build the result one clause at a time and run it after each meaningful change.",
                "hint_2": "Return `order_id, product_name, ROUND( quantity * unit_price - quantity * unit_price * COALESCE(discount_pct, 0) / 100, 2 ) AS net_sales` from `sales_reporting` in that column order. Keep only rows where `order_status = 'Pending'`."
              },
              "starterCode": "-- Write the query below.",
              "solutionCode": "SELECT\n    order_id,\n    product_name,\n    ROUND(\n        quantity * unit_price\n        - quantity * unit_price * COALESCE(discount_pct, 0) / 100,\n        2\n    ) AS net_sales\nFROM sales_reporting\nWHERE order_status = 'Pending';"
            }
          }
        }
