    "m3_s01_why_sorting": {
      "title": "Why does sorting matter?",
      "prompt": "Why is sorting useful in SQL?",
      "help": {
        "concept": "Sorting makes result sets easier to scan and helps important values appear in a useful order.",
        "hint_1": "Think easier reading and comparison.",
        "hint_2": "Sorting helps you bring rows into a predictable order instead of reading them in a random-looking sequence."
      },
      "hint": "Think clearer result order.",
      "options": {
        "a": "It makes results easier to scan and compare",
        "b": "It removes the need for SELECT",
        "c": "It always changes the table itself",
        "d": "It only works for text"
      }
    },
    "m3_s01_order_by_job": {
      "title": "What does ORDER BY do?",
      "prompt": "What is the main job of `ORDER BY` in a SQL query?",
      "help": {
        "concept": "`ORDER BY` arranges the order of the returned rows.",
        "hint_1": "Think about row order.",
        "hint_2": "It does not choose the rows. It decides how the result should be arranged."
      },
      "hint": "Think arrange the result rows.",
      "options": {
        "a": "It sorts the returned rows",
        "b": "It filters rows out",
        "c": "It renames columns",
        "d": "It creates a new table"
      }
    },
